  static DateFormat monthYear(AppLang lang) => lang == AppLang.id ? _monthYearId : _monthYearEn;
  static DateFormat dateTimeMinute(AppLang lang) => lang == AppLang.id ? _dateTimeMinuteId : _dateTimeMinuteEn;

