    return GestureDetector(
      onTap: _toggle,
      child: Column(
        children: [
          CompositedTransformTarget(
            link: _link,
            child: AnimatedOpacity(
              duration: const Duration(milliseconds: 200),
              opacity: _open ? 0 : 1,
